const fn = `() => {
  // find elements that look like the results grid
  const all = document.querySelectorAll('*');
  const candidates = [];
  for (const el of all) {
    if (el.className && typeof el.className === 'string') {
      const c = el.className.toLowerCase();
      if ((c.includes('srp-results') || c.includes('results-grid') || c.includes('srp-item')) ) {
        candidates.push(el.tagName + '.' + el.className.trim().split(/\\s+/).slice(0,3).join('.') + ' (children:' + el.children.length + ')');
      }
    }
  }
  // count s-item elements and data-quid items
  const itemCount = document.querySelectorAll('.srp-item, [data-quid]').length;
  // try to find where titles live
  const h3count = document.querySelectorAll('h3').length;
  // get a container that contains h3 with title text 'Sony'
  let hit = null;
  for (const el of all) {
    if (el.textContent && el.textContent.includes('Sony WH-1000XM6') && el.children.length <= 8) {
      const t = el.textContent.trim().replace(/\\s+/g,' ').slice(0,120);
      hit = {tag: el.tagName, cls: el.className.trim().split(/\\s+/).slice(0,4).join(' '), text: t, htmlSnip: el.outerHTML.slice(0,300)};
      break;
    }
  }
  return {candidates, h3count, sampleHit: hit};
}`;
const res = await tools.cdt.evaluate_script({ pageId: 1, function: fn });
console.log(JSON.stringify(res, null, 2));

