() => {
  const ul = document.querySelector('ul.srp-results');
  if (!ul) return {note:'no ul.srp-results'};
  const lis = Array.from(ul.children);
  const out = [];
  const txt = (li, sel) => { const e = li.querySelector(sel); return e ? e.textContent.trim().replace(/\s+/g,' ').trim() : ''; };
  for (const li of lis) {
    let link = '';
    const a = li.querySelector('a');
    if (a) link = a.href;
    out.push({link, title: txt(li, '.s-item-title'), price: txt(li, '.s-item-price'), shipping: txt(li, '.s-item__shipping'), condition: txt(li, '.s-item__condition')});
  }
  return {count: out.length, items: out};
}

