const fn = `() => {
  const ul = document.querySelector('ul.srp-results');
  const lis = Array.from(ul.children);
  // Identify which li are "main" vs gallery by checking for a detail/description block
  const describe = (li, label) => {
    const fields = [];
    const walk = (el) => {
      const cls = el.className && typeof el.className === 'string' ? el.className : '';
      if (/srp-item|s-item|listItem/.test(cls)) {
        const t = (el.textContent||'').trim().replace(/\\s+/g,' ').slice(0,80);
        fields.push('[' + cls.split(/\\s+/).join(',') + '] ' + t);
      }
    };
    [li].concat(Array.from(li.querySelectorAll('*'))).forEach(walk);
    const link = (li.querySelector('a')||{}).href;
    return {label, count: li.childElementCount, fields, link};
  };
  return { totalLis: lis.length, a: describe(lis[0],'li0'), b: describe(lis[1],'li1'), c: describe(lis[2],'li2') };
}`;
const raw = await tools.cdt.evaluate_script({ pageId: 1, function: fn });
const jsonPart = raw.slice(raw.indexOf('```json') + 7, raw.lastIndexOf('```'));
console.log(JSON.parse(jsonPart.trim()), null, 2);

