const fn = `() => {
  const ul = document.querySelector('ul.srp-results');
  const lis = Array.from(ul.children);
  const extract = (li) => {
    const card = li.firstElementChild; if (!card) return null;
    const q = (sel) => { const e = card.querySelector(sel); return e ? e.textContent.trim().replace(/\\s+/g,' ').trim() : ''; };
    const linkEl = card.querySelector('.s-card__link') || card.querySelector('a');
    let url = linkEl ? linkEl.href : '';
    const m = url.match(/\\/itm\\/(\\d+)/);
    const itemId = m ? m[1] : '';
    // shipping: all attribute-row texts
    const attrRows = Array.from(card.querySelectorAll('.s-card__attribute-row')).map(el => (el.textContent||'').trim().replace(/\\s+/g,' ').trim());
    return {itemId, url, titleAttr: linkEl ? (linkEl.getAttribute('title')||'') : '', textContent: card.textContent.trim().replace(/\\s+/g,' ').slice(0,140), condition: q('.s-card__subtitle'), price: q('.s-card__price'), attrRows};
  };
  const all = lis.map(extract).filter(Boolean);
  return {n: all.length, items: all};
}`;
const raw = await tools.cdt.evaluate_script({ pageId: 1, function: fn });
const jsonPart = raw.slice(raw.indexOf('```json') + 7, raw.lastIndexOf('```'));
const obj = JSON.parse(jsonPart.trim());
console.log('n items:', obj.n);
obj.items.forEach((it, i) => console.log(i + ': ' + JSON.stringify(it)));

