const js = `
() => {
  const cards = Array.from(document.querySelectorAll('ul.srp-results > li'));
  const out = [];
  for (const card of cards) {
    // title: most reliable is the link text within .s-card__title, but strip noise
    const titleEl = card.querySelector('.s-card__title a');
    let title = '';
    if (titleEl) {
      title = titleEl.textContent.trim();
      // remove common eBay suffixes/noise
      title = title.replace(/\\bopens? in a new window or tab\\b/gi, '').trim();
      title = title.replace(/\\s+/g, ' ').trim();
    }
    const subtitle = card.querySelector('.s-card__subtitle');
    const condition = subtitle ? subtitle.textContent.trim().replace(/\\s+/g,' ') : '';
    const attrRows = Array.from(card.querySelectorAll('.s-card__attribute-row'));
    // price: first attribute row usually has the price; shipping: last row text like "Free shipping" or "+$X.X0 shipping"
    let priceText = '';
    let shipText = '';
    if (attrRows.length) {
      const rows = attrRows.map(r => r.textContent.trim().replace(/\\s+/g,' ').replace(/^\\s*/,''));
      // find row containing a $ price that isn't shipping
      for (const r of rows) {
        if (/^\\$/.test(r) && !/shipping/i.test(r)) { priceText = r; }
      }
      const shipRow = rows.find(r => /ship/i.test(r));
      shipText = shipRow || '';
    }
    // link href for URL
    const a = card.querySelector('a');
    let href = '';
    if (a && a.href) {
      href = a.href;
    }
    out.push({ title, condition, priceText, shipText, href });
  }
  return out;
}
`;
const result = await tools["cdt"]["evaluate_script"]({ pageId: 1, function: js, format: "function", waitForStableDom: false });
return result;

