const js = `
() => {
  const cards = Array.from(document.querySelectorAll('ul.srp-results > li'));
  const seen = new Set();
  const out = [];
  for (const card of cards) {
    const titleEl = card.querySelector('.s-card__title a');
    let title = titleEl ? titleEl.textContent.trim() : '';
    title = title.replace(/\\bopens? in a new window or tab\\b/gi,'').trim().replace(/\\s+/g,' ');
    const subtitle = card.querySelector('.s-card__subtitle');
    const condition = subtitle ? subtitle.textContent.trim().replace(/\\s+/g,' ') : '';
    const attrRows = Array.from(card.querySelectorAll('.s-card__attribute-row'));
    let priceText = '', shipText = '', priceNum = null;
    if (attrRows.length) {
      const rows = attrRows.map(r => r.textContent.trim().replace(/\\s+/g,' ').replace(/^\\s*/,''));
      for (const r of rows) {
        if (/^\\$/.test(r) && !/shipping/i.test(r)) priceText = r;
      }
      const shipRow = rows.find(r => /ship/i.test(r));
      shipText = shipRow || '';
    }
    // numeric price from priceText (leading $ amount, e.g. "$269.99" or "$A$B")
    if (priceText) {
      const m = priceText.match(/\\$([0-9]+(?:\\.[0-9]+)?)/);
      if (m) priceNum = parseFloat(m[1]);
    }
    // url from card link, strip tracking params
    let a = card.querySelector('.srp-link, a');
    let href = '';
    const allA = Array.from(card.querySelectorAll('a'));
    for (const aa of allA) { if (/\\/itm\\//.test(aa.href)) { href = aa.href; break; } }
    if (href) {
      try {
        const u = new URL(href);
        const id = (u.pathname.match(/\\/itm\\/(\\w+)/)||[])[1];
        if (id) seen.add(id);
        if (!seen.has(id + 'x')) {
          seen.add(id + 'x');
          // strip tracking params
          for (const p of ['_nkw','_sacat','_skc','rt','dc','LH_ItemCondition']) u.searchParams.delete(p);
          const url = u.origin + u.pathname;
          out.push({ id, title, condition, priceText, shipText, priceNum, url });
        }
      } catch(e) {}
    }
  }
  return JSON.stringify(out);
}
`;
const result = await tools["cdt"]["evaluate_script"]({ pageId: 1, function: js, format: "function", waitForStableDom: false });
// result is the object returned; the .value field holds the string per wrapper
return typeof result === 'string' ? result : (result && result.value) || JSON.stringify(result);

