const res = await tools["cdt"]["evaluate_script"]({ pageId: 1, function: js, format: "function", waitForStableDom: false });
let raw = (res && res.value) || res;
if (typeof raw !== 'string') raw = JSON.stringify(raw);
// strip CAPTURED| prefix, split items by | then each is a JSON object string
raw = raw.replace(/^CAPTURED\\|/, '');
const itemStrs = raw.split('|').filter(Boolean).map(s => s.trim()).filter(s => s.startsWith('{'));
const items = itemStrs.map(s => JSON.parse(s));

// ---- Filter: relevant Sony WH-1000XM6 over-ear headphones, exclude XM5/XM4/earbuds/accessories/gaming ----
function isRelevant(it){
  const t = it.title.toUpperCase();
  const hasTitle = (k) => t.includes(k);
  // Earbuds = WF-1000 / WF1000 → exclude
  if (/WF-?1000/.test(t)) return false;
  // XM4 or XM5 model → exclude (but watch for "XM5" inside "XM6"? no). Also avoid partial matches.
  // Use word-ish checks
  const isXM5 = /WH-?1000XM5|WH1000XM5|\\bXM5\\b/.test(t);
  const isXM4 = /WH-?1000XM4|WH1000XM4|\\bXM4\\b/.test(t);
  if (isXM5 || isXM4) return false;
  // must be an over-ear headphone: WH-1000 XM6, or WH1000XM6, or "Collexion" (XM6 editions = WH-1000XX),
  // or explicitly "Wireless NC Headphones" referring to XM6.
  const isXM6Model = /WH-?1000XM6|WH1000XM6/.test(t);
  const isCollexion = /COLLEXION/.test(t);
  const isGamingHeadset = /INZONE|GAME.*HEADSET|H9 II|Gaming Headset/.test(t);
  if (isGamingHeadset) return false;
  // "The Best" branded XM6 titles are relevant
  const rel = isXM6Model || isCollexion;
  // Accept plain "Sony Wireless NC Headphones Platinum Refurbished" + Deco Kit (likely XM6) since price tier matches
  if (!rel && /WIRELESS NC HEADPHONES/.test(t) && /REFURBISHED/.test(t)) return true;
  return rel;
}

const relevant = items.filter(isRelevant).sort((a,b)=> (a.priceNum||0)-(b.priceNum||0));
